import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel source for matrix-vector multiplication (A @ B)
matmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* __A, const float* __B, float* __C, int M, int K) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * K) {
        int i = idx / K; // row index
        int j = idx % K; // column index (unused for B)
        float sum = 0.0f;
        for (int kk = 0; kk < K; ++kk) {
            sum += __A[i * K + kk] * __B[kk];
        }
        __C[idx] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto out = torch::zeros_like(A);

    int M = A.size(0);
    int K = A.size(1);
    const int block_size = 256;
    const int num_blocks = (M * K + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float()>, B.data_ptr<float()>, out.data_ptr<float()>, M, K);

    return out;
}
"""

cpp_sources = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

matmul_cuda = load_inline(
    name="matmul_cuda",
    cpp_sources=cpp_sources,
    cuda_sources=matmul_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul_cuda = matmul_cuda

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix-vector multiplication.

        Args:
            A: Input matrix of shape (M, K).
            B: Input vector of shape (K, 1).

        Returns:
            Output vector of shape (M, 1).
        """
        return self.matmul_cuda(A, B)
